-- Migration: 0221 qData 资产地图本地导入数据集。
-- Purpose: 建立资产拥有的导入数据集、业务行和编辑日志，迁入五十四条公开元信息及一千零四十三条字段；复用已上架的十七条目录。
-- Depends on: 0219_asset_qdata-market-import.sql 已执行；现有单租户资产目录、标签及市场表结构完整，不依赖治理元数据导入。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；以真实来源编号匹配已有数据集，存在即跳过整个数据集，不覆盖人工修改的字段、业务行或日志。
-- Rollback: 单事务失败完整回滚；提交后删除导入数据会丢失本地编辑与审计，必须先备份并核验引用，不提供自动破坏性回滚。
-- 风险：导入目录与本地技术交付独立，绝不创建虚假数据源、元数据或技术快照编号；新增三十七条地图目录保持未上架，不继承来源发布和授权状态。
-- 来源：2026-10-22 经用户授权读取 qData 资产地图；仅保留公开元信息、字段和质量任务白名单，不保留连接地址、密码、用户与联系方式。
-- 事务边界：结构、目录和元信息在一个事务中提交；完整可读业务行由下一编号迁移导入，源站失败与文件仅元信息保持明确覆盖状态。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '300s';

CREATE TABLE IF NOT EXISTS dh_asset_import_dataset (
    asset_id bigint NOT NULL PRIMARY KEY REFERENCES dh_asset_data_asset(id) ON DELETE CASCADE,
    source_asset_id varchar(64),
    source_name varchar(256),
    source_type varchar(64),
    source_data_count bigint,
    imported_row_count bigint NOT NULL DEFAULT 0,
    complete boolean NOT NULL DEFAULT false,
    columns_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    file_info_json jsonb,
    quality_json jsonb,
    lineage_json jsonb,
    revision integer NOT NULL DEFAULT 0,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CONSTRAINT ck_asset_import_dataset_count CHECK (imported_row_count >= 0 AND (source_data_count IS NULL OR source_data_count >= 0)),
    CONSTRAINT ck_asset_import_dataset_revision CHECK (revision >= 0),
    CONSTRAINT ck_asset_import_dataset_columns CHECK (jsonb_typeof(columns_json) = 'array')
);
COMMENT ON TABLE dh_asset_import_dataset IS '数据资产-本地导入数据集，与外部数据库执行和市场授权独立';
COMMENT ON COLUMN dh_asset_import_dataset.asset_id IS '本地资产编号，数据集范围与对象权限按此资产校验';
COMMENT ON COLUMN dh_asset_import_dataset.source_asset_id IS '来源公开资产编号，仅用于来源追溯，不作为本地技术或授权主键';
COMMENT ON COLUMN dh_asset_import_dataset.source_name IS '来源公开连接名称，不含连接地址或认证信息';
COMMENT ON COLUMN dh_asset_import_dataset.source_type IS '来源公开连接产品类型，例如 Doris 或 HDFS';
COMMENT ON COLUMN dh_asset_import_dataset.source_data_count IS '导出时源预览报告的总行数，源端不可读时为空';
COMMENT ON COLUMN dh_asset_import_dataset.imported_row_count IS '当前已导入的本地有效业务行数量';
COMMENT ON COLUMN dh_asset_import_dataset.complete IS '此次源端可读数据是否完整导入，不能将不可读源端当成完整空表';
COMMENT ON COLUMN dh_asset_import_dataset.columns_json IS '字段元信息白名单，使用导入命名空间标识，不建立虚假治理表引用';
COMMENT ON COLUMN dh_asset_import_dataset.file_info_json IS '公开文件描述、业务归属与来源事实，仅白名单保留公开文件业务目录，不保留连接地址和访问凭证';
COMMENT ON COLUMN dh_asset_import_dataset.quality_json IS '来源只读质量任务与评估规则快照，不包含执行连接配置';
COMMENT ON COLUMN dh_asset_import_dataset.lineage_json IS '来源只读血缘图快照，未知时为空，不伪造任务或节点关系';
COMMENT ON COLUMN dh_asset_import_dataset.revision IS '本地数据集字段编辑修订号，用于比较并交换并发控制';
COMMENT ON COLUMN dh_asset_import_dataset.creator IS '创建者';
COMMENT ON COLUMN dh_asset_import_dataset.create_time IS '创建时间';
COMMENT ON COLUMN dh_asset_import_dataset.updater IS '更新者';
COMMENT ON COLUMN dh_asset_import_dataset.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_import_dataset.deleted IS '是否逻辑删除';
CREATE UNIQUE INDEX IF NOT EXISTS uk_asset_import_dataset_source ON dh_asset_import_dataset(source_asset_id)
    WHERE deleted=0 AND source_asset_id IS NOT NULL;

CREATE SEQUENCE IF NOT EXISTS dh_asset_import_row_seq;
CREATE TABLE IF NOT EXISTS dh_asset_import_row (
    id bigint NOT NULL PRIMARY KEY DEFAULT nextval('dh_asset_import_row_seq'),
    asset_id bigint NOT NULL REFERENCES dh_asset_import_dataset(asset_id) ON DELETE CASCADE,
    ordinal integer NOT NULL,
    row_json jsonb NOT NULL,
    revision integer NOT NULL DEFAULT 0,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CONSTRAINT ck_asset_import_row_ordinal CHECK (ordinal > 0),
    CONSTRAINT ck_asset_import_row_revision CHECK (revision >= 0),
    CONSTRAINT ck_asset_import_row_object CHECK (jsonb_typeof(row_json) = 'object')
);
ALTER SEQUENCE dh_asset_import_row_seq OWNED BY dh_asset_import_row.id;
COMMENT ON TABLE dh_asset_import_row IS '数据资产-本地导入业务行，数值单元格使用无损十进制字符串';
COMMENT ON COLUMN dh_asset_import_row.id IS '本地业务行编号，独立于来源行内标识';
COMMENT ON COLUMN dh_asset_import_row.asset_id IS '所属本地资产编号';
COMMENT ON COLUMN dh_asset_import_row.ordinal IS '稳定的本地行顺序，保留来源数据中的重复行';
COMMENT ON COLUMN dh_asset_import_row.row_json IS '业务行对象，数值采用十进制字符串，禁止经浮点数中转';
COMMENT ON COLUMN dh_asset_import_row.revision IS '业务行编辑修订号，用于比较并交换并发控制';
COMMENT ON COLUMN dh_asset_import_row.creator IS '创建者';
COMMENT ON COLUMN dh_asset_import_row.create_time IS '创建时间';
COMMENT ON COLUMN dh_asset_import_row.updater IS '更新者';
COMMENT ON COLUMN dh_asset_import_row.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_import_row.deleted IS '是否逻辑删除';
CREATE UNIQUE INDEX IF NOT EXISTS uk_asset_import_row_ordinal ON dh_asset_import_row(asset_id, ordinal) WHERE deleted=0;

CREATE SEQUENCE IF NOT EXISTS dh_asset_import_row_log_seq;
CREATE TABLE IF NOT EXISTS dh_asset_import_row_log (
    id bigint NOT NULL PRIMARY KEY DEFAULT nextval('dh_asset_import_row_log_seq'),
    asset_id bigint NOT NULL REFERENCES dh_asset_data_asset(id) ON DELETE CASCADE,
    row_id bigint NOT NULL,
    revision integer NOT NULL,
    before_json jsonb,
    after_json jsonb,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CONSTRAINT ck_asset_import_row_log_revision CHECK (revision >= 0)
);
ALTER SEQUENCE dh_asset_import_row_log_seq OWNED BY dh_asset_import_row_log.id;
COMMENT ON TABLE dh_asset_import_row_log IS '数据资产-本地导入业务行编辑日志，保留变更前后值与操作人';
COMMENT ON COLUMN dh_asset_import_row_log.id IS '本地编辑日志编号';
COMMENT ON COLUMN dh_asset_import_row_log.asset_id IS '所属本地资产编号';
COMMENT ON COLUMN dh_asset_import_row_log.row_id IS '本地业务行编号，历史日志不依赖业务行继续存在';
COMMENT ON COLUMN dh_asset_import_row_log.revision IS '此次变更对应的业务行修订号';
COMMENT ON COLUMN dh_asset_import_row_log.before_json IS '变更前的完整业务行对象，新增时为空';
COMMENT ON COLUMN dh_asset_import_row_log.after_json IS '变更后的完整业务行对象，删除时为空';
COMMENT ON COLUMN dh_asset_import_row_log.creator IS '实际操作人，由可信登录身份提供';
COMMENT ON COLUMN dh_asset_import_row_log.create_time IS '变更时间';
COMMENT ON COLUMN dh_asset_import_row_log.updater IS '更新者';
COMMENT ON COLUMN dh_asset_import_row_log.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_import_row_log.deleted IS '是否逻辑删除';
CREATE INDEX IF NOT EXISTS idx_asset_import_row_log_asset ON dh_asset_import_row_log(asset_id, create_time DESC, id DESC)
    WHERE deleted=0;

LOCK TABLE dh_asset_data_asset, dh_asset_import_dataset, dh_asset_tag, dh_asset_tag_rel IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE qdata_map_metadata_seed (content jsonb NOT NULL) ON COMMIT DROP;
