$metadata$::jsonb);

DO $metadata_import$
DECLARE
    relation_name text;
    sequence_name text;
    sequence_value bigint;
    sequence_called boolean;
    first_id numeric;
    item jsonb;
    asset_code_value text;
    external_code_value text;
    local_asset_id bigint;
    local_tag_id bigint;
    tag_name text;
    existing record;
    columns_value jsonb;
BEGIN
    -- 持有业务表写锁后对齐本次会分配编号的现有序列，序列重启随事务失败回滚。
    FOREACH relation_name IN ARRAY ARRAY['dh_asset_data_asset', 'dh_asset_tag', 'dh_asset_tag_rel'] LOOP
        sequence_name := relation_name || '_seq';
        IF NOT EXISTS (SELECT 1 FROM pg_sequence WHERE seqrelid = sequence_name::regclass AND seqincrement = 1 AND NOT seqcycle) THEN
            RAISE EXCEPTION '导入要求序列使用步长一且禁止循环：%', sequence_name;
        END IF;
        EXECUTE format('SELECT last_value, is_called FROM %I', sequence_name) INTO sequence_value, sequence_called;
        EXECUTE format('SELECT greatest(coalesce(max(id),0)::numeric + 1, $1::numeric + $2) FROM %I', relation_name)
            INTO first_id USING sequence_value, CASE WHEN sequence_called THEN 1 ELSE 0 END;
        IF first_id > 9223372036854771711 THEN RAISE EXCEPTION '导入序列剩余空间不足'; END IF;
        EXECUTE format('ALTER SEQUENCE %I RESTART WITH %s', sequence_name, first_id);
    END LOOP;

    FOR item IN SELECT value FROM qdata_map_metadata_seed seed, jsonb_array_elements(seed.content) LOOP
        SELECT * INTO existing FROM dh_asset_import_dataset WHERE source_asset_id = item->>'source_id';
        IF FOUND THEN
            IF existing.deleted<>0 THEN RAISE EXCEPTION '来源数据集已人工删除，拒绝重建：%', item->>'source_id'; END IF;
            CONTINUE;
        END IF;
        IF item->>'market_id' IS NOT NULL THEN
            asset_code_value := 'QDATA_MARKET_' || (item->>'market_id');
            external_code_value := 'qdata:market:' || (item->>'market_id');
        ELSE
            asset_code_value := 'QDATA_ASSET_' || (item->>'source_id');
            external_code_value := 'qdata:asset:' || (item->>'source_id');
        END IF;
        SELECT * INTO existing FROM dh_asset_data_asset WHERE asset_code = asset_code_value AND deleted = 0;
        IF FOUND THEN
            IF existing.external_code IS DISTINCT FROM external_code_value THEN
                RAISE EXCEPTION '本地来源目录身份冲突，拒绝覆盖：%', item->>'source_id';
            END IF;
            local_asset_id := existing.id;
        ELSE
            IF item->>'market_id' IS NOT NULL THEN RAISE EXCEPTION '缺少已经迁入的市场目录：%', item->>'market_id'; END IF;
            INSERT INTO dh_asset_data_asset(asset_code, catalog_item_urn, asset_name, asset_type, table_name,
                layer, subject_domain_name, row_count, field_count, description, status, view_count,
                share_attr, share_attribute, catalog_revision, tech_available, external_code, creator, updater,
                create_time, update_time)
            VALUES (asset_code_value, 'urn:datahub:catalog:qdata:asset:' || (item->>'source_id'), item->>'asset_name',
                (item->>'asset_type')::smallint, item->>'table_name', item->>'layer', item->>'subject_domain_name',
                (item->>'row_count')::bigint, (item->>'field_count')::integer, item->>'description', 0, 0,
                0, 0, 0, 0, external_code_value, 'migration:0221', 'migration:0221',
                coalesce((item->>'create_time')::timestamp, CURRENT_TIMESTAMP),
                coalesce((item->>'update_time')::timestamp, CURRENT_TIMESTAMP)) RETURNING id INTO local_asset_id;
            FOR tag_name IN SELECT value FROM jsonb_array_elements_text(item->'tags') WITH ORDINALITY AS tags(value,position)
                GROUP BY value ORDER BY min(position) LOOP
                SELECT id INTO local_tag_id FROM dh_asset_tag WHERE name = tag_name AND deleted = 0;
                IF local_tag_id IS NULL THEN
                    INSERT INTO dh_asset_tag(name, color, status, creator, updater)
                    VALUES(tag_name, '#4266f4', 0, 'migration:0221', 'migration:0221') RETURNING id INTO local_tag_id;
                END IF;
                INSERT INTO dh_asset_tag_rel(asset_id, tag_id, creator, updater)
                VALUES(local_asset_id, local_tag_id, 'migration:0221', 'migration:0221');
            END LOOP;
        END IF;
        IF EXISTS (SELECT 1 FROM dh_asset_import_dataset WHERE asset_id = local_asset_id) THEN
            RAISE EXCEPTION '本地资产已存在不同来源的数据集，拒绝覆盖：%', local_asset_id;
        END IF;
        SELECT coalesce(jsonb_agg(column_value || jsonb_build_object('resourceUrn',
            'urn:datahub:asset:import:' || local_asset_id || ':column:' || (column_value->>'id')) ORDER BY position), '[]'::jsonb)
          INTO columns_value FROM jsonb_array_elements(item->'columns') WITH ORDINALITY AS source_column(column_value, position);
        INSERT INTO dh_asset_import_dataset(asset_id, source_asset_id, source_name, source_type, source_data_count,
            imported_row_count, complete, columns_json, file_info_json, quality_json, lineage_json,
            revision, creator, updater)
        VALUES(local_asset_id, item->>'source_id', item->>'source_name', item->>'source_type',
            (item->>'source_data_count')::bigint, 0, false, columns_value, item->'file_info',
            nullif(item->'quality', 'null'::jsonb), nullif(item->'lineage', 'null'::jsonb),
            0, 'migration:0221', 'migration:0221');
    END LOOP;
END;
$metadata_import$;

COMMIT;
